    need(bytes.toString('base64') === input.bodyBase64, 'CROSSREF_DOCUMENT_ENCODING_INVALID');
  }
  need(bytes.length > 0 && bytes.length <= MAX_BODY, 'CROSSREF_DOCUMENT_SIZE_LIMIT', 413);
