  need(Number.isSafeInteger(raw.expectedRevision)&&raw.expectedRevision>=1,'EXPECTED_REVISION_REQUIRED');
  need(EXTRACTION_PUBLICATION_ACTIONS.includes(raw.action),'PUBLICATION_ACTION_INVALID');
