          need(before.value.bytes>0,'PIPELINE_EMPTY_INPUT');
          need(before.value.bytes<=SERVICE_LIMITS.maxInputBytes,'PIPELINE_INPUT_SIZE_INVALID');
          need(!selectedSignal.aborted,'RESEARCH_OBJECT_REVIEW_STOPPED');
