  }else if(tag==='object'){
    need(Array.isArray(payload)&&payload.every(pair=>Array.isArray(pair)&&pair.length===2&&typeof pair[0]==='string')&&
      new Set(payload.map(pair=>pair[0])).size===payload.length,'EXTRACTION_TYPED_OBJECT_INVALID');
