        }else{
          need(object(choice.answer),'EXTRACTION_RESOLUTION_ANSWER_REQUIRED');
          fields(choice.answer,['status','value','bases','context','note','derivation'],'EXTRACTION_RESOLUTION_ANSWER_FIELDS_INVALID');
